G=load()
def comps(g,bg):
    H,W=len(g),len(g[0]); seen=set(); res=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and (r,c) not in seen:
                col=g[r][c]; st=[(r,c)]; seen.add((r,c)); cl=[]
                while st:
                    a,b=st.pop(); cl.append((a,b))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            p=(a+dr,b+dc)
                            if 0<=p[0]<H and 0<=p[1]<W and p not in seen and g[p[0]][p[1]]==col:
                                seen.add(p); st.append(p)
                res.append((col,cl))
    return res
def solve(g):
    bg=collections.Counter(x for row in g for x in row).most_common(1)[0][0]
    cs=comps(g,bg)
    out=[row[:] for row in g]
    # group by (norm shape, color): canonical = the largest count instance(s)
    from collections import defaultdict
    by=defaultdict(list)
    for col,cl in cs:
        rs=[r for r,c in cl]; cc=[c for r,c in cl]
        nm=tuple(sorted((r-min(rs),c-min(cc)) for r,c in cl))
        by[(nm,col)].append(cl)
    for (nm,col),lst in by.items():
        # canonical = largest instance(s) (by size); partial = smaller instances of same shape/color
        sz={tuple(cl) for cl in lst}
        cand=[cl for cl in lst if len(cl)==max(len(c) for c in lst)]
        if len(cand)<len(lst):
            for ref in cand:
                refset=set(ref)
                for cl in lst:
                    if cl==ref: continue
                    for (r,c) in cl:
                        ar=r-min([rr for rr,_ in ref]); ac=c-min([cc for _,cc in ref])
                        mr=min(rr for rr,_ in ref); mc=min(cc for _,cc in ref)
                        tr,tc=mr+ar,mc+ac
                        if 0<=tr<len(out) and 0<=tc<len(out[0]) and out[tr][tc]==bg:
                            out[tr][tc]=col
    return out
